#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>

class Solution {
private:
    std::vector<int> getPrimes(int x) {
        std::vector<int> res;
        for (int d = 2; d * d <= x; ++d) {
            if (x % d == 0) {
                res.push_back(d);
                while (x % d == 0) x /= d;
            }
        }
        if (x > 1) res.push_back(x);
        return res;
    }
public:
    int longestSubarrayAtMostKPrimes(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<std::vector<int>> factors(n);
        for (int i = 0; i < n; ++i) factors[i] = getPrimes(nums[i]);

        std::unordered_map<int, int> counts;
        int left = 0, maxLen = 0;
        for (int right = 0; right < n; ++right) {
            for (int p : factors[right]) counts[p]++;
            while ((int)counts.size() > k) {
                for (int p : factors[left]) {
                    counts[p]--;
                    if (counts[p] == 0) counts.erase(p);
                }
                left++;
            }
            maxLen = std::max(maxLen, right - left + 1);
        }
        return maxLen;
    }
};

import java.util.*;

class Solution {
    private List<Integer> getPrimes(int x) {
        List<Integer> res = new ArrayList<>();
        for (int d = 2; d * d <= x; d++) {
            if (x % d == 0) {
                res.add(d);
                while (x % d == 0) x /= d;
            }
        }
        if (x > 1) res.add(x);
        return res;
    }

    public int longestSubarrayAtMostKPrimes(int[] nums, int k) {
        int n = nums.length;
        List<List<Integer>> factors = new ArrayList<>();
        for (int x : nums) factors.add(getPrimes(x));

        Map<Integer, Integer> counts = new HashMap<>();
        int left = 0, maxLen = 0;
        for (int right = 0; right < n; right++) {
            for (int p : factors.get(right)) {
                counts.put(p, counts.getOrDefault(p, 0) + 1);
            }
            while (counts.size() > k) {
                for (int p : factors.get(left)) {
                    int c = counts.get(p) - 1;
                    if (c == 0) counts.remove(p);
                    else counts.put(p, c);
                }
                left++;
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

function getPrimes(x) {
    const res = [];
    for (let d = 2; d * d <= x; d++) {
        if (x % d === 0) {
            res.push(d);
            while (x % d === 0) x = Math.floor(x / d);
        }
    }
    if (x > 1) res.push(x);
    return res;
}

function longestSubarrayAtMostKPrimes(nums, k) {
    const n = nums.length;
    const factors = nums.map(getPrimes);
    const counts = new Map();
    let left = 0, maxLen = 0;
    for (let right = 0; right < n; right++) {
        for (const p of factors[right]) {
            counts.set(p, (counts.get(p) || 0) + 1);
        }
        while (counts.size > k) {
            for (const p of factors[left]) {
                const c = counts.get(p) - 1;
                if (c === 0) counts.delete(p);
                else counts.set(p, c);
            }
            left++;
        }
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}
